import sys


class Student:
    def __init__(self, name, rollNumber, marks):
        self.name = name
        self.rollNumber = rollNumber
        self.marks = marks

    def calculate_grade(self):
        m = self.marks
        if m >= 90:
            return 'A'
        elif m >= 75:
            return 'B'
        elif m >= 50:
            return 'C'
        else:
            return 'Fail'


class GraduateStudent(Student):
    def __init__(self, name, rollNumber, marks, thesisTitle):
        super().__init__(name, rollNumber, marks)
        self.thesisTitle = thesisTitle


def main():
    data = sys.stdin.read().strip().splitlines()
    if len(data) < 4:
        return
    name = data[0].strip()
    rollNumber = int(data[1].strip())
    marks = int(data[2].strip())
    thesisTitle = data[3].strip()

    student = GraduateStudent(name, rollNumber, marks, thesisTitle)
    grade = student.calculate_grade()
    print(grade)
    print(student.thesisTitle)


if __name__ == "__main__":
    main()
